#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <math.h>
/* 15. 3Sum：纯 C / Objective-C .m 兼容实现 */
/*
15. 3Sum

Given an array S of n integers, are there elements a, b, c in S such that a + b + c = 0? Find all unique triplets in the array which gives the sum of zero.

Note: The solution set must not contain duplicate triplets.

For example, given array S = [-1, 0, 1, 2, -1, -4],

A solution set is:
[
  [-1, 0, 1],
  [-1, -1, 2]
]
*/

/**
 * Return an array of arrays of size *returnSize.
 * Note: The returned array must be malloced, assume caller calls free().
 */
typedef struct res_s {
    int **p;
    int sz;
    int n;
} res_t;
void add2res(res_t *res, int a, int b, int c) {
    int *buff = malloc(3 * sizeof(int));
    //assert(buff);
    buff[0] = a;
    buff[1] = b;
    buff[2] = c;

    if (res->sz == 0) {
        res->sz = 10;
        res->p = malloc(res->sz * sizeof(int **));
        //assert(res->p);
    } else if (res->sz == res->n) {
        res->sz *= 2;
        res->p = realloc(res->p, res->sz * sizeof(int **));
        //assert(res->p);
    }
    res->p[res->n ++] = buff;
}
int cmp(const void *a, const void *b) {
    return *(int *)a - *(int *)b;
}
int** threeSum(int* nums, int numsSize, int* returnSize) {
    int i, x, y, k;
    res_t res = { 0 };

    qsort(nums, numsSize, sizeof(int), cmp);

    for (i = 0; i < numsSize - 2; i ++) {
        if (i != 0 && nums[i] == nums[i - 1]) continue;
        x = i + 1;
        y = numsSize - 1;
        while (x < y) {
            k = nums[i] + nums[x] + nums[y];
            if (k == 0) {
                // found one
                add2res(&res, nums[i], nums[x], nums[y]);
                x ++;
                while (x < y && nums[x] == nums[x - 1]) x ++;
                y --;
                while (x < y && nums[y] == nums[y + 1]) y --;
            } else if (k < 0) {
                x ++;
                while (x < y && nums[x] == nums[x - 1]) x ++;
            } else {
                y --;
                while (x < y && nums[y] == nums[y + 1]) y --;
            }
        }
    }

    *returnSize = res.n;
    return res.p;
}

