    while (c = s[tail ++]) {
        i = c - 'a';
        cnt[i] --;
        n --;
        if (cnt[i] < 0) {
            do {
                c = s[head ++];
                j = c - 'a';
                cnt[j] ++;
                n ++;
            } while (cnt[i] < 0);
        } else if (n == 0) {   // found one
            add2res(&res, head);
            c = s[head ++]; // push one out from head
            j = c - 'a';
            cnt[j] ++;
            n ++;
        }
    }
    *returnSize = res.n;
    return res.p;
}

