int HashKey(int key) {
    while(key < 0) key += INIT_HASH_SIZE;
    return (key % INIT_HASH_SIZE);
}

void AddHash(Hash *root, int key) {
    assert(root);
    Hash *h = &root[HashKey(key)];
    if (h->key == 0 && h->count == 0) {
        h->key = key;
        h->count = 1;
    } else if (h->key == key) {
        h->count++;
    } else {
        while (h) {
            if (h->key == key) {
                h->count++;
                return;
            } else if (!h->next) {
                h->next = NewHash(key);
                return;
            }
            h = h->next;
        }
    }
}

// If hash not round return 0 on purpose.
int GetHash(Hash *root, int key) {
    Hash *h = &root[HashKey(key)];
    while(h) {
        if (h->key == key) {
            return h->count;
        }
        h = h->next;
    }
    return 0;
}

