/*
 Cyclic group generator to do matrix transpose.
 use a 1-dimension array to reprents m*n matrix.
 the result is an n*m matrix.
 */

void transpose(int *matrix, int m, int n) {
    int i, j, c;
    i = j = 0;
    int pre = matrix[0];
    int t;
    for (c = 0; c < m * n - 1; c++) { /* pay attention it's m*n-1 */
        i = (i % n) * m + (i / n);
        t = matrix[i];
        matrix[i] = pre;
        pre = t;
        if (i == j) {
            i = ++j;
            pre = matrix[i];
        }
    }
}

