void setZeroes(int **matrix, int m, int n) {
    int first_col_zero, first_row_zero;
    first_col_zero = first_row_zero = 0;
    int i, j;
    for (i = 0; i < m; i++) {
        if (matrix[i][0] == 0) {
            first_col_zero = 1;
