struct ListNode *detectCycle(struct ListNode *head) {
    struct ListNode *n, *nn;

    if (!head) return NULL;

    n = nn = head;
    do {
        n = n->next;            // one step
        nn = nn->next;
        if (nn) nn = nn->next;  // two steps
    } while (nn && n != nn);

    if (!nn) return NULL;

    // there is a cycle
    n = head;
    while (n != nn) {
        n = n->next;
        nn = nn->next;
    }

    return n;
}

