import Foundation

final class ListNode {
    var val: Int
    var next: ListNode?
    init(_ val: Int = 0, _ next: ListNode? = nil) { self.val = val; self.next = next }
}
func buildList(_ a: [Int]) -> ListNode? {
    let d = ListNode(0); var p = d
    for x in a { p.next = ListNode(x); p = p.next! }
    return d.next
}
func dumpList(_ head: ListNode?) -> [Int] {
    var out: [Int] = [], p = head
    while let n = p { out.append(n.val); p = n.next }
    return out
}

class ReverseNodesInKGroup {
    func reverseKGroup(_ head: ListNode?, _ k: Int) -> ListNode? {
        let dummy = ListNode(0)
        dummy.next = head

        var prev = dummy                             // prev = A
        while prev.next != nil {                     // A->B->C->D->E => A->D->C->B->E
            var groupTail : ListNode? = prev
            for _ in 1...k {
                groupTail = groupTail?.next
            }
            guard let _ = groupTail else {            // groupTail = D
                break
            }

            let nextGroupHead = groupTail!.next      // nextGroupHead = E
            var last = nextGroupHead                 // last = E
            var current : ListNode? = prev.next      // current = B
            while current != nil && current !== nextGroupHead {
                let next = current!.next             // next = C
                current!.next = last                 // B -> E
                last = current                       // last = B
                current = next                       // current = C
            }

            groupTail = prev.next
            prev.next = last
            prev = groupTail!
        }

        return dummy.next
    }
}

