#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <math.h>
struct ListNode{int val;struct ListNode*next;};

struct ListNode* reverseKGroup(struct ListNode* head, int k) {
    struct ListNode *node, *next;
    struct ListNode **stack;
    struct ListNode dummy = { 0 }, *p;
    int i;

    if (k <= 1) return head;

    stack = malloc(k * sizeof(struct ListNode *));
    //assert(stack);

#define PUSH(NODE) do { stack[i++] = NODE; } while (0)
#define POP(NODE) do { NODE = stack[--i]; } while (0)

    p = &dummy;

    p->next = node = head;
    while (node) {
        i = 0;
        while (i < k && node) {
            PUSH(node);
            node = node->next;
        }
        next = node;

        if (i < k) {
            free(stack);
            return dummy.next;
        }

        while (i > 0) {
            POP(node);
            p->next = node;
            p = node;
        }
        p->next = node = next;
    }

    free(stack);
    return dummy.next;
}

