        var right = lists.count - 1

        var lists = lists

        while right > 0 {
            left = 0
            while left < right {
                lists[left] = _mergeTwoLists(lists[left], lists[right])
                left += 1
                right -= 1
            }
        }

        return lists[0]
    }

    private func _mergeTwoLists(l1: ListNode?, _ l2: ListNode?) -> ListNode? {
        let dummy = ListNode(0)
