        // Insert the node at the right (MRU)
        insertNode(node, obj);

        return node->value;
    }

    return -1;
}

void lRUCachePut(LRUCache* obj, int key, int value) {
    Node* node;
    HASH_FIND_INT(hashedNodes, &key, node);

    // Check if the key exists
    if(node)
    {
