        Node* LRUNode = obj->leftMost->next;

        // Remove the left node (LRU) from the list
        removeNode(LRUNode);

        // Remove the node from the hash
        HASH_DEL(hashedNodes, LRUNode);

        // Deallocate the node
        free(LRUNode);
