#else
    ssz = 100;
    stack = malloc(ssz * sizeof(struct TreeNode *));
    //assert(stack);
    sp = 0;

#define PUSH(N) do { \
    if (ssz == sp) { \
        ssz *= 2; \
        stack = realloc(stack, ssz * sizeof(struct TreeNode *)); \
        /* assert(stack); */ \
    } \
    stack[sp ++] = N; \
} while (0)

#define POP(N) do { N = stack[-- sp]; } while (0)

    node = root;
    while (node || sp) {
        while (node) {
            PUSH(node);
            node = node->left;
        }
        POP(node);
        add2p(p, sz, n, node->val);
        node = node->right;
    }

    free(stack);
#endif

