            nodeQ.append(root)
        }

        while nodeQ.count > 0 {
            var size = nodeQ.count

            for i in 0..<size {
                let node = nodeQ.removeFirst()

                if i + 1 == size {
                    res.append(node.val)
                }

                if let left = node.left {
                    nodeQ.append(left)
                }
