 */

class FlattenBinaryTreeLinkedList {
    func flatten(_ root: TreeNode?) {
        helper(root)
    }

    private func helper(_ node: TreeNode?) -> TreeNode? {
        var node = node
        if node == nil {
            return node
        }
        if node!.left == nil && node!.right == nil {
            return node
        }

        let left = node!.left, right = node!.right
        node!.left = nil

        if let left = left {
            node!.right = left
            node = helper(left)
        }
        if let right = right {
            node!.right = right
            node = helper(right)
        }

        return node
    }
}

