import Foundation

final class TreeNode {
    var val: Int
    var left: TreeNode?
    var right: TreeNode?
    init(_ val: Int = 0) { self.val = val }
}
func buildTree(_ a: [Any]) -> TreeNode? {
    guard !a.isEmpty, !(a[0] is NSNull) else { return nil }
    let root = TreeNode((a[0] as! NSNumber).intValue)
    var q = [root], head = 0, i = 1
    while head < q.count && i < a.count {
        let n = q[head]; head += 1
        if !(a[i] is NSNull) { n.left = TreeNode((a[i] as! NSNumber).intValue); q.append(n.left!) }
        i += 1
        if i < a.count && !(a[i] is NSNull) { n.right = TreeNode((a[i] as! NSNumber).intValue); q.append(n.right!) }
        i += 1
    }
    return root
}

class PathSumIII {
    func pathSum(_ root: TreeNode?, _ sum: Int) -> Int {
        guard let root = root else {
            return 0
        }

        var res = totalPaths(root, sum)

        let left = pathSum(root.left, sum)
        let right = pathSum(root.right, sum)

        return res + left + right
    }

    func totalPaths(_ root: TreeNode?, _ sum: Int) -> Int {
        guard let root = root else {
            return 0
        }

        var res = 0
        if sum == root.val {
            res += 1
        }

        res += totalPaths(root.left, sum - root.val)
        res += totalPaths(root.right, sum - root.val)

        return res
    }
}

