    }

    if (node->right) {
        lca = traversal(node->right, p, q);
        if (lca) return lca;
    }

    if (node == p && (match(node->left, q) || match(node->right, q))) return node;

    if (match(node->left, p) && match(node->right, q)) return node;

    return NULL;
}
