struct result_stack {
    char** chessboard;
    struct result_stack* next;
};

// A Node() function to create a new stack node.
struct result_stack* Node() {
    struct result_stack* node = (struct result_stack*)malloc(sizeof(struct result_stack));
    node -> next = NULL;
    node -> chessboard = NULL;
    return node;
}

