            if nums[mid] == target {
                return mid
            } else if nums[mid] < target {
                left = mid
            } else {
                right = mid
            }
        }

        if nums[right] < target {
            return right + 1
        }
        if nums[left] >= target {
            return left
        }

        return right
    }
