    struct Node* next;
} Node;

Node* nodeCreate(int val) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = val;
    node->next = NULL;
    return node;
}

void nodePush(Node** obj, int val) {
    assert(obj);
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = val;
    node->next = *obj;
    *obj = node;
}

void nodePop(Node** obj) {
    assert(obj);
    if (*obj) {
        Node* tmp = *obj;
        *obj = tmp->next;
        free(tmp);
    }
}

// A structure to represent a stack.
typedef struct {
    int size;
    Node* top;
} MyStack;

MyStack* stackCreate()
{
    MyStack* stack = (MyStack*)malloc(sizeof(MyStack));
    stack->size = 0;
    stack->top = NULL;
    return stack;
}

void stackPush(MyStack* stack, int item)
{
    if (!stack->top) {
        stack->top = nodeCreate(item);
    } else {
        nodePush(&stack->top, item);
    }
    stack->size++;
}

void stackPop(MyStack* stack)
{
    nodePop(&stack->top);
    stack->size--;
}

int stackTop(MyStack* stack)
{
    assert(stack);
    assert(stack->top);
    return stack->top->value;
}

