    assert(obj);
    if(!obj->stk) {
        obj->stk = stackCreate();
        obj->minStk = stackCreate();
    }
    stackPush(obj->stk, val);
    if (obj->minStk->top) {
        int minTop = stackTop(obj->minStk);
        if ( val < minTop) {
            stackPush(obj->minStk, val);
        } else {
            stackPush(obj->minStk, minTop);
        }
    } else {
        stackPush(obj->minStk, val);
    }
}

void minStackPop(MinStack* obj) {
    assert(obj);
    stackPop(obj->stk);
    stackPop(obj->minStk);
