import Foundation

final class Solution {
    func canJump(_ nums: [Int]) -> Bool {
        var maximumIndex = nums[0]

        for (currentIndex, value) in nums.enumerated(){

            if currentIndex > maximumIndex{
                return false
            }

            maximumIndex = max(maximumIndex, currentIndex + value)
        }

        return true
    }
}

