#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <math.h>

bool canPartition(int* nums, int numsSize) {
    int t, s, i, k;
    bool *dp, ans;

    t = 0;
    for (i = 0; i < numsSize; i ++) {
        t += nums[i];
    }

    if (t & 1) return false;

    t >>= 1;

    dp = calloc(t + 1, sizeof(bool));
    //assert(dp);

    dp[0] = true;
    for (i = 0; !dp[t] && i < numsSize; i ++) {
        k = nums[i];
        for (s = t; s >= k; s --) {
            dp[s] = dp[s - k];
        }
    }

    ans = dp[t];

    free(dp);

    return ans;
}

