    int i, j;

    if (!m || !n) return 0;

    for (i = 0; i < m; i ++) {
        for (j = 0; j < n; j ++) {
            if (i == 0 || j == 0) {
                path[i][j] = 1;
            } else {
                path[i][j] = path[i][j - 1] + path[i - 1][j];
            }
        }
    }
